package local.z6panel;

import android.content.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Foreground-only, one bounded Commons attempt; no periodic background job. */
final class WallpaperOnline {
 private static final AtomicBoolean BUSY=new AtomicBoolean();
 private volatile boolean cancelled; private volatile HttpURLConnection connection;
 static String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date());}
 void cancel(){cancelled=true;HttpURLConnection c=connection;if(c!=null)c.disconnect();}
 private HttpURLConnection connect(String url)throws IOException {URL u=new URL(url);for(int redirect=0;redirect<3;redirect++){if(cancelled)throw new InterruptedIOException();if(!"https".equals(u.getProtocol())||!(u.getHost().equals("commons.wikimedia.org")||u.getHost().equals("upload.wikimedia.org")||u.getHost().equals("thumb.wikimedia.org")))throw new IOException("Origen de fondo no permitido");HttpURLConnection c=(HttpURLConnection)u.openConnection();connection=c;c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Z6Panel/0.15.0 (personal wallpaper; MediaWiki API)");int code=c.getResponseCode();if(code==200)return c;if(code>=300&&code<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException("Redirección incompleta");u=new URL(u,location);continue;}c.disconnect();throw new IOException("Wikimedia no está disponible ("+code+")");}throw new IOException("Demasiadas redirecciones de Wikimedia");}

 private static int cap(Context c){return Math.min(1920,WallpaperImages.maximum(c));}
 static boolean sufficient(Context c){File f=file(c);if(f==null)return false;android.graphics.BitmapFactory.Options bounds=new android.graphics.BitmapFactory.Options();bounds.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeFile(f.getPath(),bounds);int[] target=WallpaperImages.size(c,cap(c));return bounds.outWidth>=target[0]-1&&bounds.outHeight>=target[1]-1;}
 private int neededWidth(Context c,JSONObject info){int w=info.optInt("width"),h=info.optInt("height");int[] t=WallpaperImages.size(c,cap(c));if(w<t[0]||h<t[1]||h<=0)return 0;long needed=Math.max(t[0],((long)t[1]*w+h-1)/h);for(int step:new int[]{1280,1920,3840})if(needed<=step)return step;return 0;}
 private JSONObject json(String url)throws Exception{HttpURLConnection c=connect(url);try(InputStream in=c.getInputStream()){return new JSONObject(new String(WallpaperStore.readLimited(in,1024*1024),"UTF-8"));}finally{c.disconnect();}}
 private JSONObject page(String selector,int width)throws Exception{return json("https://commons.wikimedia.org/w/api.php?action=query&"+selector+"&prop=imageinfo&iiprop=url%7Csize%7Cmime%7Cextmetadata&iiextmetadatafilter=Artist%7CLicenseShortName%7CLicenseUrl&iiurlwidth="+width+"&format=json&formatversion=2").getJSONObject("query").getJSONArray("pages").getJSONObject(0);}
 private boolean suitable(JSONObject info,JSONObject meta){if(meta==null)return false;String license=value(meta,"LicenseShortName");return (license.startsWith("CC BY")||license.equals("CC0")||license.equals("Public domain"))&&info.optString("mime").equals("image/jpeg")&&info.optInt("width")>=info.optInt("height")&&!info.optString("thumburl").isEmpty()&&!value(meta,"Artist").isEmpty();}
 static final class Candidate {final int id,width,height;final String name,url;Candidate(int id,String name,String url,int width,int height){this.width=width;this.height=height;this.id=id;this.name=name.replaceFirst("^File:","");this.url=url;}}
 List<Candidate> catalog(Context c)throws Exception {String url="https://commons.wikimedia.org/w/api.php?action=query&generator=categorymembers&gcmtitle=Category%3AFeatured_pictures_of_landscapes&gcmtype=file&gcmnamespace=6&gcmlimit=30&prop=imageinfo&iiprop=url%7Csize%7Cmime%7Cextmetadata&iiextmetadatafilter=Artist%7CLicenseShortName%7CLicenseUrl&iiurlwidth=330&format=json&formatversion=2";JSONArray pages=json(url).getJSONObject("query").getJSONArray("pages");List<Candidate> out=new ArrayList<>();for(int i=0;i<pages.length();i++){JSONObject p=pages.getJSONObject(i);JSONArray infos=p.optJSONArray("imageinfo");if(infos==null||infos.length()==0)continue;JSONObject info=infos.getJSONObject(0);if(suitable(info,info.optJSONObject("extmetadata"))&&neededWidth(c,info)>0)out.add(new Candidate(p.getInt("pageid"),p.optString("title"),info.getString("thumburl"),info.optInt("width"),info.optInt("height")));}if(out.isEmpty())throw new IOException("No hay paisajes con resolución suficiente para este inicio");return out;}
 private void download(String url,File target,int limit)throws Exception{HttpURLConnection c=connect(url);boolean ok=false;try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(target)){byte[] buffer=new byte[16384];int count=0,n;while((n=in.read(buffer))!=-1){if(cancelled)throw new InterruptedIOException();count+=n;if(count>limit)throw new IOException("Imagen demasiado grande");out.write(buffer,0,n);}ok=true;}finally{c.disconnect();if(!ok)target.delete();}}
 void thumbnail(Candidate item,File target)throws Exception{if(!target.isFile())download(item.url,target,512*1024);}
 String update(Context c,boolean manual)throws Exception{SharedPreferences prefs=c.getSharedPreferences("panel",0);long now=System.currentTimeMillis();boolean current=file(c)!=null&&today().equals(prefs.getString("wallpaper_daily_date",""));if(current&&sufficient(c))return "El paisaje de hoy ya está guardado";long delay=manual?60000:3600000;if(now-prefs.getLong("wallpaper_daily_attempt",0)<delay)return "Se conservará el paisaje anterior; vuelve a intentar más tarde";if(!BUSY.compareAndSet(false,true))return "Actualización en curso";try{prefs.edit().putLong("wallpaper_daily_attempt",now).apply();String title=credit(c).optString("title");if(current&&!title.isEmpty())return save(c,"titles="+URLEncoder.encode(title,"UTF-8"));List<Candidate> items=catalog(c);Candidate item=items.get(Math.floorMod(today().hashCode(),items.size()));return save(c,"pageids="+item.id);}finally{BUSY.set(false);}}
 String useCandidate(Context c,Candidate item)throws Exception{if(!BUSY.compareAndSet(false,true))throw new IOException("Hay otra descarga en curso");try{return save(c,"pageids="+item.id);}finally{BUSY.set(false);}}
 private String save(Context c,String selector)throws Exception{WallpaperStore store=new WallpaperStore(c);File temp=null,prepared=null;try{JSONObject selected=page(selector,cap(c)),info=selected.getJSONArray("imageinfo").getJSONObject(0);if(!suitable(info,info.optJSONObject("extmetadata")))throw new IOException("El paisaje ya no está disponible");int required=neededWidth(c,info);if(required==0)throw new IOException("Este paisaje no permite un fondo nítido y ligero; elige otro");int[] target=WallpaperImages.size(c,cap(c));if(info.optInt("thumbwidth")<target[0]||info.optInt("thumbheight")<target[1]){selected=page(selector,required);info=selected.getJSONArray("imageinfo").getJSONObject(0);}
  temp=File.createTempFile("daily-choice-",".tmp",c.getCacheDir());download(info.getString("thumburl"),temp,5*1024*1024);android.graphics.Bitmap bitmap=WallpaperImages.frame(temp,target[0],target[1]);int width=bitmap.getWidth(),height=bitmap.getHeight();if(width<target[0]-1||height<target[1]-1){bitmap.recycle();throw new IOException("La descarga no alcanza la resolución necesaria; se conserva tu fondo");}prepared=new File(store.dir,"daily-"+UUID.randomUUID()+".jpg");long limit=(cap(c)>=1920?2:1)*WallpaperImages.MB;try{for(int quality:new int[]{85,80,75}){try(FileOutputStream out=new FileOutputStream(prepared)){if(!bitmap.compress(android.graphics.Bitmap.CompressFormat.JPEG,quality,out))throw new IOException("No se pudo guardar el paisaje");}if(prepared.length()<=limit)break;}}finally{bitmap.recycle();}if(prepared.length()>limit)throw new IOException("El paisaje supera el límite de almacenamiento");if(cancelled)throw new InterruptedIOException();JSONObject meta=info.getJSONObject("extmetadata");JSONObject credit=new JSONObject().put("file",prepared.getName()).put("title",selected.optString("title")).put("author",value(meta,"Artist")).put("license",value(meta,"LicenseShortName")).put("licenseUrl",value(meta,"LicenseUrl")).put("source",info.optString("descriptionurl")).put("date",today()).put("width",width).put("height",height);WallpaperStore.writeJson(new File(store.dir,"daily.json"),credit.toString());c.getSharedPreferences("panel",0).edit().putString("wallpaper_daily_date",today()).putLong("wallpaper_daily_attempt",System.currentTimeMillis()).apply();String keep=prepared.getName();long bytes=prepared.length();prepared=null;File[] old=store.dir.listFiles((d,n)->n.startsWith("daily-")&&n.endsWith(".jpg")&&!n.equals(keep));if(old!=null)for(File f:old)f.delete();return "Paisaje listo · "+width+" × "+height+" · "+WallpaperImages.bytes(bytes);
 }finally{if(temp!=null)temp.delete();if(prepared!=null)prepared.delete();if(connection!=null)connection.disconnect();}}
 static void recordFailure(Context c,int id,String name,Exception error){try{WallpaperStore.writeJson(new File(c.getFilesDir(),"landscape-last-error.json"),new JSONObject().put("time",System.currentTimeMillis()).put("id",id).put("name",name).put("error",error.toString()).toString());}catch(Exception ignored){}}
 static JSONObject lastFailure(Context c){try(InputStream in=new FileInputStream(new File(c.getFilesDir(),"landscape-last-error.json"))){return new JSONObject(new String(WallpaperStore.readLimited(in,16384),"UTF-8"));}catch(Exception ignored){return new JSONObject();}}
 static String value(JSONObject metadata,String key){JSONObject v=metadata.optJSONObject(key);return v==null?"":v.optString("value");}
 static JSONObject credit(Context context){try(InputStream in=new FileInputStream(new File(new WallpaperStore(context).dir,"daily.json"))){return new JSONObject(new String(WallpaperStore.readLimited(in,32768),"UTF-8"));}catch(Exception ignored){return new JSONObject();}}
 static File file(Context context){String name=credit(context).optString("file");if(!name.matches("daily-[a-f0-9-]+\\.jpg"))return null;File f=new File(new WallpaperStore(context).dir,name);return f.isFile()?f:null;}
}
